import re
import six

from ute_admin_infomodel.parsing.converter import convert_value, convert_dist_name

from ..event import ModelAction
from .parser import \
    InfoModelEventParser, \
    InfoModelConditionParser, \
    InfoModelEventParameterPredicateParser, \
    InfoModelEventObjectPredicateParser, \
    InfoModelValueMatcherParser
from .matchers import \
    BasicEventMatcher, \
    RemoveEventMatcher, \
    ExtendedRemoveMatcher, \
    CreateEventMatcher, \
    ChangeEventMatcher, \
    UpdateEventMatcher, \
    SequenceMatcher


class EventMatcherFactory(object):
    def __init__(self):
        self.parser = InfoModelEventParser()

        self.constructors = {
            'reset': self._create_reset_event_matcher,
            'remove': self._create_remove_event_matcher,
            'create': self._create_create_event_matcher,
            'change': self._create_change_event_matcher,
            'update': self._create_update_event_matcher
        }

        self.comparator_functions = {
            '': lambda x, y: x == y,
            '=': lambda x, y: x == y,
            '>': lambda x, y: x > y,
            '<': lambda x, y: x < y,
            '>=': lambda x, y: x >= y,
            '<=': lambda x, y: x <= y,
            '!': lambda x, y: x != y,
            '!=': lambda x, y: x != y,
            '*': lambda x, y: True,
            '*=': lambda x, y: True,
            'regex': lambda x, y: True if re.match(str(y), str(x)) else False,
            '=regex': lambda x, y: True if re.match(str(y), str(x)) else False,
            'empty': lambda x, y: not x and x != 0,
            '=empty': lambda x, y: not x and x != 0,
            '!empty': lambda x, y: x or x == 0,
            '!=empty': lambda x, y: x or x == 0,
            'not-empty': lambda x, y: x or x == 0,
        }
        self.default_dist_name_regex = "^.*$"
        self.default_value_matcher = lambda x: True
        self.default_occurences_matcher = lambda x: x >= 1

    def create_event_matcher(self, event_description, current_infomodel_state=None):
        """Parse event descrition and return proper event matcher."""
        parsed_event = self.parser.parse(event_description)
        action = self._get_action(parsed_event)
        matcher = self.constructors[action](event_description, parsed_event)
        if current_infomodel_state:
            matcher.set_infomodel_state(current_infomodel_state)
        return matcher

    def create_event_sequence_matcher(self, events, current_infomodel_state=None):
        """Create event sequence matcher."""
        event_mathers = [self.create_event_matcher(e, current_infomodel_state) for _, e in self._sort(events)]
        return SequenceMatcher(event_mathers)

    def _sort(self, events):
        return sorted(six.iteritems(events), key=self._get_event_index)

    def _get_event_index(self, event):
        events_id, event_description = event
        return [int(text) if text.isdigit() else text.lower() for text in re.split('([0-9]+)', events_id)]

    def create_any_event_matcher(self):
        """Create event matcher for any action."""
        actions = [ModelAction.ON_RESET, ModelAction.ON_REMOVE, ModelAction.ON_UPDATE]
        return BasicEventMatcher("any event", actions, self.default_occurences_matcher)

    def create_any_change_matcher(self):
        """Create any change matcher"""
        return BasicEventMatcher("any change", [ModelAction.ON_UPDATE], self.default_occurences_matcher)

    def create_reset_matcher(self):
        """Create basic reset matcher"""
        return BasicEventMatcher("reset", [ModelAction.ON_RESET], self.default_occurences_matcher)

    def _create_reset_event_matcher(self, event_description, parsed_event):
        occurence_matcher = self._get_occurences_matcher(parsed_event)
        return BasicEventMatcher(event_description, [ModelAction.ON_RESET], occurence_matcher)

    def _create_remove_event_matcher(self, event_description, parsed_event):
        occurence_matcher = self._get_occurences_matcher(parsed_event)
        dist_name_regex = self._get_dist_name_regex(parsed_event)
        object_predicate = self._get_object_predicate(parsed_event)
        if object_predicate:
            return ExtendedRemoveMatcher(event_description, occurence_matcher, dist_name_regex, object_predicate)
        return RemoveEventMatcher(event_description, occurence_matcher, dist_name_regex)

    def _create_create_event_matcher(self, event_description, parsed_event):
        occurence_matcher = self._get_occurences_matcher(parsed_event)
        dist_name_regex = self._get_dist_name_regex(parsed_event)
        object_predicate = self._get_object_predicate(parsed_event)
        return CreateEventMatcher(event_description, occurence_matcher, dist_name_regex, object_predicate)

    def _create_change_event_matcher(self, event_description, parsed_event):
        occurence_matcher = self._get_occurences_matcher(parsed_event)
        dist_name_regex = self._get_dist_name_regex(parsed_event)
        change_predicate = self._get_change_predicate(parsed_event)
        return ChangeEventMatcher(event_description, occurence_matcher, dist_name_regex, change_predicate)

    def _create_update_event_matcher(self, event_description, parsed_event):
        occurence_matcher = self._get_occurences_matcher(parsed_event)
        dist_name_regex = self._get_dist_name_regex(parsed_event)
        change_predicate = self._get_change_predicate(parsed_event)
        return UpdateEventMatcher(event_description, occurence_matcher, dist_name_regex, change_predicate)

    def _get_action(self, parsed_event):
        action = getattr(parsed_event, 'action')
        return action or 'update'

    def _get_occurences_matcher(self, parsed_event):
        if not parsed_event.occurences_condition:
            return self.default_occurences_matcher
        condition = InfoModelConditionParser().parse(parsed_event.occurences_condition)

        comparator = self.comparator_functions[condition.operator]
        comparative_value = int(condition.value)
        return lambda x: comparator(x, comparative_value)

    def _get_dist_name_regex(self, parsed_event):
        if not parsed_event.dist_name:
            return self.default_dist_name_regex
        return convert_dist_name(parsed_event.dist_name)

    def _get_object_predicate(self, parsed_event):
        if not parsed_event.predicate:
            return None
        parsed_predicate = InfoModelEventObjectPredicateParser().parse(parsed_event.predicate)
        parameter = parsed_predicate.name
        condition = InfoModelConditionParser().parse(" ".join(parsed_predicate.condition.asList()))
        value_matcher = self._get_value_matcher(condition)
        return (parameter, value_matcher, None)

    def _get_change_predicate(self, parsed_event):
        if not parsed_event.predicate:
            return None
        parsed_predicates = InfoModelEventParameterPredicateParser().parse(parsed_event.predicate)
        parameter = parsed_predicates.name
        if parsed_predicates.previous:
            previous = InfoModelValueMatcherParser().parse("".join(parsed_predicates.previous.asList()))
        else:
            previous = ""

        if parsed_predicates.new:
            new = InfoModelValueMatcherParser().parse("".join(parsed_predicates.new.asList()))
        else:
            new = ""

        prevoiuos_param_value_matcher = self._get_value_matcher(previous)
        new_param_value_matcher = self._get_value_matcher(new)
        return (parameter, prevoiuos_param_value_matcher, new_param_value_matcher)

    def _get_value_matcher(self, predicate):
        if not predicate:
            return self.default_value_matcher
        comparator = self.comparator_functions[predicate.operator]
        if predicate.value:
            reference_value = convert_value(predicate.value) if predicate.value[0] != '"' else convert_value(predicate.value[1:-1])
        else:
            reference_value = convert_value(predicate.value)
        return lambda x: comparator(x, reference_value)
